(* [comment removed for export] *)
Fixpoint var_ranges (kn : list kentry) : vranges :=
  match kn with
  | [] => []
  | KRange (EVar n) lo hi :: r => (n, lo, hi) :: var_ranges r
  | _ :: r => var_ranges r
  end.

