Inductive mfact : Type :=
| MCell  (a : zexp) (w : nat) (v : zexp)   (* [comment removed for export] *)
| MZeroC (a : zexp) (n : Z)                (* [comment removed for export] *)
| MRo    (a : zexp) (w : nat) (v : zexp)   (* [comment removed for export] *)
| MZero  (a : zexp) (n : Z)                (* [comment removed for export] *)
| MFill  (a : zexp) (n : Z) (c : Z)        (* [comment removed for export] *)
| MImg   (lo hi : Z)                       (* [comment removed for export] *)
| MWr    (a : zexp) (n : Z)                (* [comment removed for export] *)
(* [comment removed for export] *)
| MZeroS (a : zexp) (n : zexp)             (* [comment removed for export] *)
| MWrS   (a : zexp) (n : zexp).            (* [comment removed for export] *)

Inductive pfact : Type :=
| PVar   (n : nat) (lo hi : Z)             (* [comment removed for export] *)
| PRange (e : zexp) (lo hi : Z)            (* [comment removed for export] *)
| PDisj  (a1 : zexp) (n1 : Z) (a2 : zexp) (n2 : Z)    (* [comment removed for export] *)
| PDisjS (a1 n1 a2 n2 : zexp).             (* [comment removed for export] *)

Definition cellw (w : nat) (z : Z) : cell :=
  match w with
  | 8%nat => C8 (Z_to_bv 64 z)
  | 4%nat => C4 (Z_to_bv 64 z)
  | 2%nat => C2 (Z_to_bv 64 z)
  | _ => C1 (Z_to_bv 8 z)
  end.
Definition is_cellw (w : nat) : bool :=
  match w with 8%nat | 4%nat | 2%nat | 1%nat => true | _ => false end.

Definition zeros (n : Z) : list byte := repeat (Z_to_bv 8 0) (Z.to_nat n).

