Definition range_clear (S : list (Z * Z)) (VR : vranges) (bn : zexp * zexp) : bool :=   (* [comment removed for export] *)
  match zbnd VR (fst bn), zbnd VR (ZAdd (fst bn) (snd bn)) with
  | Some (lo, _), Some (_, hi) => forallb (fun s => (hi <=? fst s) || (snd s <=? lo)) S
  | _, _ => false
  end.

